package com.yuegang.zhihui.system.api;
import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.common.web.*;import com.yuegang.zhihui.system.application.*;import com.yuegang.zhihui.system.security.*;import jakarta.servlet.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/internal/v1/authorizations") public final class InternalAuthorizationController{private final AuthorizationService service;private final InternalServiceVerifier verifier;public InternalAuthorizationController(AuthorizationService s,InternalServiceVerifier v){service=s;verifier=v;}@GetMapping("/{userId}")public ApiResponse<AuthoritySnapshot>snapshot(@PathVariable String userId,HttpServletRequest r){verifier.verify(r,"ygh-auth-service");return ApiResponse.success(service.snapshot(userId),TraceIdResolver.resolve(r));}}
